CREATE DATABASE kaveri;
DROP TABLE IF EXISTS legacy_reservations;

CREATE TABLE legacy_reservations (
    row_id          TEXT,
    guest_name      TEXT,
    guest_email     TEXT,
    guest_phone     TEXT,
    guest_city      TEXT,
    hotel_name      TEXT,
    hotel_city      TEXT,
    hotel_star      TEXT,
    room_numbers    TEXT,
    room_type       TEXT,
    guests_count    TEXT,
    checkin         TEXT,
    checkout        TEXT,
    nightly_rate    TEXT,
    total_paid      TEXT,
    payment_method  TEXT,
    status          TEXT,
    notes           TEXT
);

